'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const sample=()=>[{id:'K001',name:'佐藤 はな',kana:'さとう はな',area:'肩・首',time:'10:00',visits:8},{id:'K002',name:'鈴木 陸',kana:'すずき りく',area:'腰まわり',time:'11:30',visits:3},{id:'K003',name:'高橋 あおい',kana:'たかはし あおい',area:'背中・肩',time:'14:00',visits:1},{id:'K004',name:'田中 悠',kana:'たなか ゆう',area:'脚・足',time:'',visits:5}];
let clients=sample(),records=[],side='前面',color='#d38368',drawing=false,current=[],strokes={},draftOwner='K001';
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function go(id){$$('.view').forEach(e=>e.classList.toggle('active',e.id===id));$$('[data-go]').forEach(e=>e.classList.toggle('active',e.dataset.go===id));if(id==='record')history();window.scrollTo(0,0)}
$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
function person(p,appointment=false){return `<div class="person">${appointment?`<time>${esc(p.time)}</time>`:''}<span class="face">${esc(p.name.slice(0,1))}</span><div class="info"><h3>${esc(p.name)} <span class="muted small">さん</span></h3><p class="muted">${esc(p.area)} · ${esc(p.id)}${appointment?'':` · ${p.visits}回来店`}</p></div><span class="tag ${p.visits===1?'amber':''}">${p.visits===1?'初回来店':'再来'}</span><button class="link open-person" data-id="${esc(p.id)}" aria-label="${esc(p.name)}さんの記録を開く">開く →</button></div>`}
function render(){const query=$('#search').value.trim();$('#clientList').innerHTML=clients.filter(p=>[p.name,p.kana,p.id].some(s=>s.includes(query))).map(p=>person(p)).join('')||'<p class="empty">該当するカルテがありません。</p>';$('#appointments').innerHTML=clients.filter(p=>p.time).slice(0,3).map(p=>person(p,true)).join('');const selected=$('#personSelect').value;$('#personSelect').innerHTML=clients.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} さん · ${esc(p.id)}</option>`).join('');if(clients.some(p=>p.id===selected))$('#personSelect').value=selected;$('#count').textContent=clients.length;$('#recordCount').textContent=records.length;$$('.open-person').forEach(b=>b.onclick=()=>{if($('#personSelect').value!==b.dataset.id&&hasDraft()&&!confirm('入力中の下書きを破棄して別の顧客を開きますか？'))return;clearDraft();$('#personSelect').value=b.dataset.id;draftOwner=b.dataset.id;go('record')})}
$('#search').oninput=render;['#add','#add2'].forEach(s=>$(s).onclick=()=>$('#newClient').showModal());$('#closeDialog').onclick=()=>$('#newClient').close();$('#newForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name)return;clients.push({id:'K'+crypto.randomUUID(),name,kana:f.get('kana').trim(),area:f.get('area').trim()||'未記入',time:'',visits:0});render();e.target.reset();$('#newClient').close();toast('顧客カルテを登録しました');go('clients')};
const cal=$('#calendar');cal.innerHTML=['月','火','水','木','金','土','日'].map(d=>`<span>${d}</span>`).join('')+'<span></span>'.repeat(3)+Array.from({length:31},(_,i)=>`<button class="${i===27?'active':i===29?'has':''}" data-day="${i+1}">${i+1}</button>`).join('');$$('[data-day]').forEach(b=>b.onclick=()=>{$$('[data-day]').forEach(x=>x.classList.toggle('active',x===b));$('#daynote').textContent=b.dataset.day==='28'?'28日 · 3名の来店予定':`${b.dataset.day}日 · 登録された予定はありません`});
$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('.recordpane').forEach(p=>p.hidden=p.id!==b.dataset.tab);$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));if(b.dataset.tab==='history')history()});
$('#checks').innerHTML=['前回からの体調の変化を確認した','通院・服薬・施術を避ける事項を確認した','施術内容を説明し、本人の意向を確認した'].map((t,i)=>`<div class="check"><input type="checkbox" id="check${i}"><label for="check${i}">${t}</label></div>`).join('');
const canvas=$('#draw'),ctx=canvas.getContext('2d');function redraw(){ctx.clearRect(0,0,1000,840);for(const stroke of [...(strokes[side]||[]),...(current.length?[{color,points:current}]:[])]){ctx.beginPath();ctx.strokeStyle=stroke.color;ctx.lineWidth=7;ctx.lineCap='round';ctx.lineJoin='round';stroke.points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));if(stroke.points.length===1){const [x,y]=stroke.points[0];ctx.lineTo(x+.1,y+.1)}ctx.stroke()}}
function point(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)/r.width*1000,(e.clientY-r.top)/r.height*840]}canvas.onpointerdown=e=>{if(e.button!==0)return;drawing=true;canvas.setPointerCapture(e.pointerId);current=[point(e)];redraw()};canvas.onpointermove=e=>{if(!drawing)return;current.push(point(e));redraw()};function end(){if(!drawing)return;drawing=false;(strokes[side]??=[]).push({color,points:current});current=[];redraw()}canvas.onpointerup=end;canvas.onpointercancel=end;
$$('[data-side]').forEach(b=>b.onclick=()=>{end();side=b.dataset.side;$('#sideLabel').textContent=side;$('#bodyshape').style.transform=side.includes('側面')?'translateX(110px) scaleX(.56)':'';$$('[data-side]').forEach(x=>x.classList.toggle('active',x===b));redraw()});$$('[data-color]').forEach(b=>b.onclick=()=>{color=b.dataset.color;$$('[data-color]').forEach(x=>x.classList.toggle('active',x===b))});$('#undo').onclick=()=>{(strokes[side]||[]).pop();redraw()};$('#clear').onclick=()=>{if((strokes[side]||[]).length&&confirm('この面の書き込みを消しますか？')){strokes[side]=[];redraw()}};
const fields=['safetyNote','complaint','observation','treatment','response'];function hasDraft(){return fields.some(k=>$('#'+k).value)||Object.values(strokes).some(s=>s.length)||$$('#checks input').some(x=>x.checked)}function clearDraft(){fields.forEach(k=>$('#'+k).value='');$$('#checks input').forEach(x=>x.checked=false);strokes={};redraw()}
$('#personSelect').onchange=()=>{if(hasDraft()&&!confirm('入力中の下書きを破棄して顧客を切り替えますか？')){$('#personSelect').value=draftOwner;return}clearDraft();draftOwner=$('#personSelect').value;history()};
$('#save').onclick=()=>{if(!hasDraft()){toast('メモや人体図を記入してください');return}if(!$('#date').value){toast('施術日を入力してください');return}const r={id:crypto.randomUUID(),clientId:$('#personSelect').value,date:$('#date').value,createdAt:new Date().toISOString(),checks:$$('#checks input').map(x=>x.checked),strokes:structuredClone(strokes)};fields.forEach(k=>r[k]=$('#'+k).value);records.unshift(r);clearDraft();render();history();toast('このセッションに記録しました')};
function history(){const rs=records.filter(r=>r.clientId===$('#personSelect').value);$('#history').innerHTML='<h2>このセッションの記録</h2>'+ (rs.map(r=>`<div class="person" style="display:block"><h3>${esc(r.date)}</h3><p class="muted">本人申告：${esc(r.complaint||'未記入')}</p><p>施術：${esc(r.treatment||'未記入')}</p><p class="muted">反応：${esc(r.response||'未記入')}</p><p class="muted">人体図 ${Object.keys(r.strokes).filter(s=>r.strokes[s].length).map(esc).join('・')||'未記入'}</p><button class="link load-record" data-id="${r.id}">内容を下書きに読み込む →</button></div>`).join('')||'<p class="empty">まだ記録がありません。<br>今日の気づきを残してみましょう。</p>');$$('.load-record').forEach(b=>b.onclick=()=>{if(hasDraft()&&!confirm('現在の下書きを置き換えますか？'))return;const r=records.find(r=>r.id===b.dataset.id);fields.forEach(k=>$('#'+k).value=r[k]||'');$$('#checks input').forEach((x,i)=>x.checked=!!r.checks[i]);strokes=structuredClone(r.strokes);$('#date').value=r.date;redraw();$('[data-tab="memo"]').click();toast('新しい記録の下書きとして読み込みました')})}
const b64=a=>btoa(String.fromCharCode(...new Uint8Array(a))),unb64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function derive(p,salt,usage){const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(p),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',hash:'SHA-256',salt,iterations:600000},base,{name:'AES-GCM',length:256},false,[usage])}
$('#export').onclick=async()=>{const p=$('#password').value;if(p.length<12){toast('12文字以上のパスフレーズを入力してください');return}if(p!==$('#password2').value){toast('パスフレーズが一致しません');return}if(hasDraft()){toast('先に施術記録を保存してください（下書きは出力対象外です）');return}const btn=$('#export');btn.disabled=true;try{const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await derive(p,salt,'encrypt'),data=new TextEncoder().encode(JSON.stringify({version:1,clients,records}));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,data);const bytes=new Uint8Array(cipher);let binary='';for(const b of bytes)binary+=String.fromCharCode(b);const blob=new Blob([JSON.stringify({version:1,salt:b64(salt),iv:b64(iv),cipher:btoa(binary)})],{type:'application/octet-stream'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='komorebi-backup.komorebi';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);$('#password').value=$('#password2').value='';toast('暗号化ファイルを作成しました')}catch(e){toast('暗号化に失敗しました。HTTPS対応のブラウザでお試しください')}finally{btn.disabled=false}};
function validData(d){return d&&d.version===1&&Array.isArray(d.clients)&&d.clients.length>0&&d.clients.length<10000&&d.clients.every(p=>['id','name','kana','area','time'].every(k=>typeof p[k]==='string')&&Number.isFinite(p.visits))&&new Set(d.clients.map(p=>p.id)).size===d.clients.length&&Array.isArray(d.records)&&d.records.every(r=>typeof r.id==='string'&&typeof r.date==='string'&&d.clients.some(p=>p.id===r.clientId)&&fields.every(k=>typeof r[k]==='string')&&Array.isArray(r.checks)&&r.strokes&&Object.values(r.strokes).every(list=>Array.isArray(list)&&list.every(s=>/^#[0-9a-f]{6}$/i.test(s.color)&&Array.isArray(s.points)&&s.points.every(p=>Array.isArray(p)&&p.length===2&&p.every(n=>typeof n==='number'&&Number.isFinite(n)&&Math.abs(n)<100000)))))}
$('#import').onclick=async()=>{const file=$('#importFile').files[0];if(!file||!$('#importPassword').value){toast('ファイルとパスフレーズを指定してください');return}if(file.size>10000000){toast('ファイルは10MB以下にしてください');return}const btn=$('#import');btn.disabled=true;try{const env=JSON.parse(await file.text());if(env.version!==1)throw Error();const salt=unb64(env.salt),iv=unb64(env.iv);if(salt.length!==16||iv.length!==12)throw Error();const key=await derive($('#importPassword').value,salt,'decrypt');const data=JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv},key,unb64(env.cipher))));if(!validData(data))throw Error();if(!confirm('読込み内容を確認できました。現在のデータと下書きを置き換えますか？'))return;clients=data.clients;records=data.records;clearDraft();render();draftOwner=$('#personSelect').value;$('#importPassword').value='';toast('暗号化ファイルから復元しました')}catch(e){toast('復元できません。ファイルやパスフレーズをご確認ください')}finally{btn.disabled=false}};
$('#reset').onclick=()=>{if(confirm('入力したデータを消してサンプルに戻しますか？')){clients=sample();records=[];clearDraft();render();draftOwner=$('#personSelect').value;toast('サンプルに戻しました')}};window.addEventListener('beforeunload',e=>{if(records.length||hasDraft()){e.preventDefault();e.returnValue=''}});render();history();
